/* Protótipo de UX. Todos os registros e documentos abaixo são ilustrativos.
   Ações alteram apenas esta sessão local; nenhum dado é enviado a um servidor. */
const $ = s => document.querySelector(s);
const icons = {
 home:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 gauge:'<path d="M3 17a9 9 0 1 1 18 0M12 13l4-4"/><circle cx="12" cy="13" r="1"/>',
 file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8M8 17h5"/>',
 ship:'<path d="M12 3v3M8 6h8v5M5 12V9h14v3M3 13l9-3 9 3-3 6M6 19l-3-6M3 21c2-2 4 2 6 0s4 2 6 0 4 2 6 0"/>',
 chart:'<path d="M3 3v18h18M7 16v-5M12 16V7M17 16v-8"/>',
 shield:'<path d="M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6"/>',
 settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',
 check:'<path d="M5 12l4 4L19 6"/>',
 circle:'<circle cx="12" cy="12" r="9"/><path d="M8 12l3 3 5-6"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
 link:'<path d="M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',
 search:'<circle cx="10.5" cy="10.5" r="7"/><path d="m16 16 5 5"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',
 down:'<path d="M12 3v12m-5-5 5 5 5-5M5 17v4h14v-4"/>',
 back:'<path d="M19 12H5m5-5-5 5 5 5"/>',
 alert:'<path d="m12 3 10 18H2zM12 9v5M12 17h.01"/>'
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.file}</svg>`;
const money = n => n == null ? '—' : 'USD ' + n.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});
const shortMoney = n => 'USD ' + n.toLocaleString('pt-BR');
const tag = (text,tone='',i='') => `<span class="tag ${tone}">${i?icon(i):''}${text}</span>`;
const btn = (text,action,extra='',style='',i='') => `<button class="btn ${style}" data-action="${action}" ${extra}>${i?icon(i):''}${text}</button>`;
const seed = [
 {id:'0011',q:'0001',version:3,route:'Shanghai → Santos',agent:'Agente Alpha',po:'PO-2026-084',bl:'ALPHA260811',container:'DEMO0011223',amount:4425,billed:4620,stage:'ready',kind:'difference',eta:'04 set 2026',status:'Liberado',reference:'Tabela Ásia · segundo semestre/2026'},
 {id:'0012',q:'0002',version:2,route:'Ningbo → Itapoá',agent:'Agente Beta',po:'PO-2026-091',bl:'BETA260812',container:'DEMO0044556',amount:3210,billed:null,stage:'missing',kind:'missing',eta:'06 set 2026',status:'Liberado',reference:'Proposta Beta · segundo semestre/2026'},
 {id:'0010',q:'0003',version:1,route:'Hamburgo → Santos',agent:'Agente Gamma',po:'PO-2026-077',bl:'GAMMA260810',container:'DEMO0077889',amount:5080,billed:5400,stage:'ready',kind:'difference',eta:'01 set 2026',status:'Liberado',reference:'Tabela Europa · segundo semestre/2026'},
 {id:'0009',q:'0004',version:2,route:'Busan → Navegantes',agent:'Agente Alpha',po:'PO-2026-069',bl:'ALPHA260809',container:'DEMO0099112',amount:2860,billed:2860,stage:'clean',kind:'clean',eta:'28 ago 2026',status:'Liberado',reference:'Tabela Ásia · segundo semestre/2026'},
 {id:'0008',q:'0005',version:1,route:'Roterdã → Santos',agent:'Agente Beta',po:'PO-2026-060',bl:'BETA260808',container:'DEMO0033445',amount:4120,billed:4120,stage:'clean',kind:'clean',eta:'27 ago 2026',status:'Liberado',reference:'Tabela Europa · segundo semestre/2026'},
 {id:'0007',q:'0006',version:2,route:'Gênova → Itapoá',agent:'Agente Gamma',po:'PO-2026-058',bl:'GAMMA260807',container:'DEMO0066778',amount:3960,billed:3960,stage:'cause',kind:'performance',eta:'26 ago 2026',status:'Liberado',reference:'Tabela Europa · segundo semestre/2026'}
];
let records = structuredClone(seed), route = {}, filter='all', search='', toastTimer;
const get = id => records.find(s=>s.id===id) || records[0];
const ref = s => `EMB-2026-${s.id}`;
const qref = s => `COT-2026-${s.q}`;
function stamp(s,event){const months={ago:7,set:8};const [day,month,year]=s.eta.split(' ');const d=new Date(Date.UTC(Number(year),months[month],Number(day)));const travel=s.kind==='performance'?43:35;d.setUTCDate(d.getUTCDate()+({approval:-travel-5,booking:-travel-3,bl:-travel,invoice:1}[event]||0));return d.toLocaleDateString('pt-BR',{day:'2-digit',month:'short',timeZone:'UTC'}).replace('.','');}
const auditUrl = (s,tab='frete') => `#auditoria/${s.id}/${tab}`;

function renderSidebar(){
 const current=route.page;
 const nav=[['Início','home','https://centrix-client-portal-prototype.vercel.app/portal/home'],['Visão Geral','gauge','https://centrix-client-portal-prototype.vercel.app/portal/visao-geral'],['Minhas Cotações','file','#cotacao/0011'],['Meus Embarques','ship','#embarque/0011'],['Inteligência','chart','https://centrix-client-portal-prototype.vercel.app/portal/inteligencia/performance'],['Auditoria','shield','#auditoria'],['Minhas Preferências','settings','https://centrix-client-portal-prototype.vercel.app/portal/preferencias']];
 $('#sidebar').innerHTML=`<a class="brand" href="#auditoria" aria-label="Freitas Centrix, Auditoria"><img class="logo" src="assets/centrix.svg" alt="Freitas Centrix"><small>Portal do Cliente</small></a><nav class="nav" aria-label="Navegação principal">${nav.map(([name,i,url])=>`<a href="${url}" ${url.startsWith('http')?'target="_blank" rel="noopener" title="Abrir no protótipo original"':''} class="${(current==='cotacao'&&i==='file')||(current==='embarque'&&i==='ship')||(current==='auditoria'&&i==='shield')?'active':''}">${icon(i)}${name}</a>`).join('')}</nav><div class="side-note"><strong>Uma jornada, o mesmo processo.</strong>O compromisso nasce na cotação, acompanha o embarque e sustenta cada conferência.</div>`;
}

function readRoute(){const parts=location.hash.replace(/^#/,'').split('/');route={page:['cotacao','embarque','auditoria'].includes(parts[0])?parts[0]:'auditoria',id:parts[1]&&/^\d{4}$/.test(parts[1])?parts[1]:null,tab:parts[2]||'frete',entry:['entrada','manual'].includes(parts[1])?parts[1]:null};}

function render(){readRoute();renderSidebar();document.body.classList.remove('menu-open');if($('#drawer').open)$('#drawer').close();const s=get(route.id);$('#main').innerHTML=route.entry==='entrada'?intakePage():route.entry==='manual'?manualResult(route.tab):route.page==='cotacao'?quotePage(s):route.page==='embarque'?shipmentPage(s):route.id?detailPage(s):overview();document.title=`Centrix · ${route.id?ref(s)+' · ':''}${route.page==='auditoria'?'Auditoria':route.page==='cotacao'?'Cotação aprovada':'Embarque'}`;}

function docRow(s,name,sub,key,badge='Vinculado',tone='green'){return `<div class="doc-row"><div class="doc-info">${icon('file')}<div><strong>${name}</strong><small>${sub}</small></div></div><div class="doc-actions">${tag(badge,tone)}${btn('Ver','doc',`data-id="${s.id}" data-doc="${key}"`,'small')}</div></div>`;}

function quotePage(s){return `<div class="breadcrumb"><span>Minhas Cotações</span><span>›</span><span>Histórico</span><span>›</span><span>${qref(s)}</span></div><div class="heading"><div><h1>${qref(s)}</h1><p>${s.route} · Marítimo FCL · ${s.po}</p></div>${tag('Aprovada · versão '+s.version,'green','check')}</div>${lifecycle(s,'cotacao')}<div class="notice">${icon('info')}<p>Recorte de continuidade da cotação existente: a condição aprovada e seus anexos são a origem da auditoria deste embarque.</p></div><div class="quote-summary gap"><section class="panel"><div class="panel-head"><h2>Proposta aprovada</h2>${tag('Compromisso preservado','green')}</div><div class="panel-body"><h3>${s.agent}</h3><p>Condição formalmente aprovada em ${stamp(s,'approval')} 2026.</p><div class="price">${money(s.amount)}</div><p class="small">Frete e taxas aprovadas · versão ${s.version}</p><div class="split-info"><dl class="facts"><div><dt>Transit time</dt><dd>35 dias</dd></div><div><dt>Free time</dt><dd>21 dias</dd></div></dl><dl class="facts"><div><dt>Transbordos</dt><dd>1</dd></div><div><dt>Forma de pagamento</dt><dd>Collect · cliente contrata</dd></div></dl></div></div></section><section class="panel"><div class="panel-head"><h2>Anexos da decisão</h2></div><div class="panel-body">${docRow(s,'Proposta comercial v'+s.version,'Fonte do compromisso aprovado','quote')}${docRow(s,s.reference,'Anexo da proposta','table')}${docRow(s,'Registro de aprovação','Versão, data e aprovador','approval')}</div></section></div><section class="panel gap"><div class="panel-body"><div class="heading" style="margin-bottom:0"><div><h2>Esta cotação já segue em auditoria</h2><p>O embarque ${ref(s)} herdou a referência aprovada. Os anexos já estão disponíveis para conferência.</p></div><a class="btn primary" href="${auditUrl(s)}">Acompanhar auditoria ${icon('arrow')}</a></div></div></section><div class="source-label gap">${icon('link')}Os valores e documentos deste recorte são demonstrativos; a navegação completa de cotação permanece no protótipo original.</div>`;}

function shipmentPage(s){return `<div class="breadcrumb"><span>Meus Embarques</span><span>›</span><span>${ref(s)}</span></div><div class="heading"><div><h1>${ref(s)}</h1><p>${s.route} · ${s.agent} · ${s.po}</p></div>${tag('Liberado','green','circle')}</div>${lifecycle(s,'embarque')}<section class="panel"><div class="panel-head"><div><h2>Acompanhamento do embarque</h2><p>Carga liberada em ${s.eta} · documentos e eventos preservados</p></div><a class="btn text" href="#cotacao/${s.id}">Ver cotação de origem ↗</a></div><div class="milestones">${['Solicitado','Prontidão','Coletado','Booking','Embarcado','Em trânsito','Chegada','Descarregado','Liberado'].map((x,i)=>`<div class="milestone"><span class="circle">✓</span>${x}<small>${i===8?s.eta.split(' 2026')[0]:'Concluído'}</small></div>`).join('')}</div></section><section class="next-action gap" style="flex-direction:row;align-items:center;justify-content:space-between"><div>${tag(state(s)[0],state(s)[1])}<h2 style="margin-top:10px">O embarque terminou. A conferência continua.</h2><p style="margin-top:7px">A cotação aprovada, o booking e os documentos finais já estão vinculados à auditoria.</p></div><a class="btn primary" href="${auditUrl(s)}">Abrir auditoria ${icon('arrow')}</a></section><div class="split-info"><section class="panel"><div class="panel-head"><h2>Documentos do embarque</h2></div><div class="panel-body">${docRow(s,'Booking confirmado','Associado à cotação aprovada','booking')}${docRow(s,'BL final · '+s.bl,'Documento de transporte','bl')}${docRow(s,'Commercial Invoice e Packing List','Documentos da mercadoria','cargo')}</div></section><section class="panel"><div class="panel-head"><h2>Dados e vínculos</h2></div><div class="panel-body"><dl class="facts"><div><dt>Cotação de origem</dt><dd><a href="#cotacao/${s.id}">${qref(s)} · versão ${s.version}</a></dd></div><div><dt>Contêiner</dt><dd>${s.container} · 40HC</dd></div><div><dt>Referência do cliente</dt><dd>${s.po}</dd></div><div><dt>Disponível para auditoria</dt><dd>Condições aprovadas, documentos e eventos realizados</dd></div></dl></div></section></div><p class="small gap">Recorte demonstrativo da ligação com Auditoria. Os demais fluxos de gestão de embarque permanecem no protótipo original.</p>`;}

function openDrawer(title,body,footer='',eyebrow='AUDITORIA · DETALHE'){const d=$('#drawer');d.innerHTML=`<div class="drawer-head"><div><div class="eyebrow">${eyebrow}</div><h2 id="dialog-title">${title}</h2></div><button class="icon-btn" data-action="close" aria-label="Fechar painel">${icon('close')}</button></div><div class="drawer-body">${body}</div>${footer?`<div class="drawer-footer">${footer}</div>`:''}`;if(!d.open)d.showModal();d.scrollTop=0;}

function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}

function escapeHTML(text){return String(text).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));}

const metrics = () => ({checked:records.filter(s=>s.billed!==null).length,cases:records.filter(s=>s.stage==='ready').length+manualEntries.filter(s=>s.billed>s.amount).length,clean:records.filter(s=>s.stage==='clean').length+manualEntries.filter(s=>s.billed===s.amount).length,value:records.filter(s=>s.stage==='ready').reduce((n,s)=>n+s.billed-s.amount,0)+manualEntries.reduce((n,s)=>n+Math.max(0,s.billed-s.amount),0)});
function caseValue(s){return s.billed===null?0:Math.max(0,s.billed-s.amount);}
function state(s){return ({ready:['Caso pronto','amber',money(caseValue(s))+' para questionar','Comparação, justificativa e evidências reunidas automaticamente.',s.exported?'Material exportado · envio não confirmado':'Pronto para usar'],missing:['Falta uma fonte','blue','Fatura de frete ainda não disponível','Cotação, booking e BL já estão vinculados.','Só esta pendência impede a conferência financeira'],clean:['Conferido automaticamente','green','Cobranças de acordo com o aprovado','Nenhuma ação necessária nas verificações cobertas.','Concluído sem intervenção'],cause:['Conclusão parcial','blue','Prazo realizado 8 dias maior','Causa não comprovada. Nenhuma responsabilidade atribuída.','Pedido de esclarecimento pronto']})[s.stage];}
function overview(){const m=metrics(),missing=records.find(s=>s.stage==='missing');return `<div class="heading"><div><h1>Auditoria</h1><p>A conferência acontece. Você entra quando há algo a resolver.</p></div><a class="btn primary" href="#auditoria/entrada">Auditar outro embarque ${icon('arrow')}</a></div><div class="overview-top"><section class="coverage">${icon('shield')}<div class="number">${m.checked}<span> / 6</span></div><div><h2>cobranças da jornada conferidas automaticamente</h2><p>Fontes reaproveitadas da cotação e do embarque.<br>${records.filter(s=>s.stage==='clean').length} embarques sem nenhuma ação necessária.</p><a href="#auditoria/0011/documentos">Ver de onde vêm as evidências →</a></div></section><section class="next-action">${tag(m.cases+' casos prontos','amber','file')}<h2>Você recebe o caso montado.</h2><p>${money(m.value)} em diferenças sustentadas pelas fontes. Argumentação e evidências prontas para levar ao fornecedor.</p><a class="btn text" href="#auditoria/0011/resultado">Abrir caso pronto →</a></section></div><div class="panel metrics"><div class="metric"><div class="label">Casos estruturados</div><div class="number">${m.cases}</div><small>Agrupados por cobrança e destinatário</small></div><div class="metric"><div class="label">Valor para questionar</div><div class="number">${money(m.value)}</div><small>Não representa economia realizada</small></div><div class="metric"><div class="label">Complementos necessários</div><div class="number">${missing?1:0}</div><small>Somente fontes que ainda não chegaram</small></div><div class="metric"><div class="label">Conferências sem ação</div><div class="number">${m.clean}</div><small>Sem aprovação ou encerramento manual</small></div></div><div class="section-title"><div><h2>Da cotação e do embarque</h2><p>Casos prontos primeiro. As entradas manuais também ficam disponíveis nesta página.</p></div></div><div id="overview-body">${portfolio()}</div>${manualPortfolio()}`;}
function portfolio(){return `<div class="toolbar"><div class="filters">${[['all','Todos'],['ready','Casos prontos'],['missing','Falta fonte'],['cause','Conclusão parcial'],['clean','Sem ação']].map(([id,label])=>`<button class="filter ${filter===id?'active':''}" data-action="filter" data-filter="${id}">${label}<span>${filtered(id).length}</span></button>`).join('')}</div><label class="search">${icon('search')}<input id="search" type="search" placeholder="Buscar embarque, cotação ou PO" aria-label="Buscar embarque, cotação ou PO" value="${escapeHTML(search)}"></label></div><div class="audit-list" id="audit-list">${rows()}</div><div class="notice gap">${icon('info')}<p><strong>Conferência e preparação no Centrix. Envio e negociação com você.</strong>O módulo entrega um caso fundamentado. Não inclui atuação da Freitas na contestação, acompanhamento do fornecedor ou recuperação de valores.</p></div>`;}
function filtered(f=filter){return records.filter(s=>f==='all'||s.stage===f).sort((a,b)=>['ready','missing','cause','clean'].indexOf(a.stage)-['ready','missing','cause','clean'].indexOf(b.stage));}
function rows(){const list=filtered().filter(s=>(ref(s)+' '+qref(s)+' '+s.po+' '+s.route+' '+s.agent).toLowerCase().includes(search.toLowerCase()));return list.length?list.map(s=>{const [label,tone,title,sub,status]=state(s);return `<article class="audit-row"><div><a class="ref" href="${auditUrl(s)}">${ref(s)}</a><div class="route">${s.route}</div><div class="meta">${qref(s)} · ${s.po}</div></div><div class="case-col">${tag(label,tone)}<div class="summary">${title}</div><div class="sub">${sub}</div></div><div class="owner-col"><div class="owner">${s.stage==='ready'?'Destino sugerido: '+s.agent:s.stage==='missing'?'Aguardando fatura':s.stage==='cause'?'Evidência de causa ausente':'Nenhuma ação sua'}</div><div class="sub">${status}</div></div><a class="row-arrow" href="${auditUrl(s,s.stage==='ready'?'resultado':s.stage==='missing'?'documentos':s.stage==='cause'?'performance':'frete')}" aria-label="Abrir auditoria ${ref(s)}">›</a></article>`;}).join(''):`<div class="empty"><h3>Nenhum embarque neste filtro</h3><p>As conferências seguem disponíveis na visão completa.</p>${btn('Limpar filtros','clear')}</div>`;}
function lifecycle(s,active='auditoria'){return `<nav class="lifecycle" aria-label="Etapas e origem da auditoria">${[['cotacao','circle','Cotação aprovada','Compromisso e anexos preservados',qref(s)+' · v'+s.version],['embarque','ship','Embarque','Documentos e eventos realizados',ref(s)],['auditoria','shield','Conferência automática','Caso montado quando há base suficiente',state(s)[0]]].map(([page,i,title,sub,label])=>`<div class="life-step ${active===page?'active':''}"><span class="step-icon">${icon(i)}</span><div><strong>${title}</strong><small>${sub}</small><a href="#${page}/${s.id}">${label} ↗</a></div></div>`).join('')}</nav>`;}
function breadcrumb(s){return `<nav class="breadcrumb" aria-label="Caminho"><a href="#auditoria">Auditoria</a><span>›</span><span>${ref(s)}</span></nav>`;}
function detailPage(s){const tab=['frete','performance','documentos','historico','resultado'].includes(route.tab)?route.tab:'frete';return `${breadcrumb(s)}<div class="heading detail-heading"><div><h1>Auditoria · ${ref(s)}</h1><p>${s.route} · ${s.agent} · ${s.po}</p></div>${tag(state(s)[0],state(s)[1])}</div>${lifecycle(s)}<div class="tabs">${[['frete','Conferência de Frete'],['performance','Performance'],['documentos','Documentos e vínculos'],['historico','Trilha automática'],['resultado','Caso pronto']].map(([id,label])=>`<a class="${tab===id?'active':''}" href="${auditUrl(s,id)}" ${tab===id?'aria-current="page"':''}>${label}</a>`).join('')}</div><div class="detail-grid"><div>${({frete:()=>freight(s),performance:()=>performance(s),documentos:()=>documents(s),historico:()=>historyPage(s),resultado:()=>resultPage(s)})[tab]()}</div><aside>${contextAside(s)}</aside></div>`;}
function contextAside(s){return `<section class="panel aside-card"><h3>Base da conferência</h3><dl class="facts"><div><dt>Referência aprovada</dt><dd><a href="#cotacao/${s.id}">${qref(s)} · v${s.version}</a></dd></div><div><dt>Valor aprovado</dt><dd>${money(s.amount)}</dd></div><div><dt>Operação</dt><dd>Importação · FOB ${s.route.split(' → ')[0]}<br>Cliente contrata · Collect</dd></div><div><dt>Documento de transporte</dt><dd>${s.bl}</dd></div><div><dt>Origem das evidências</dt><dd>Cotação + embarque + cobrança</dd></div></dl></section><section class="panel aside-card gap"><h3>Cobertura e limitações</h3>${tag(s.billed===null?'Frete · falta fatura':'Frete · fontes suficientes',s.billed===null?'blue':'green')}<p class="small gap">${s.billed===null?'Comparação financeira ainda não executada.':'Linhas da cobrança comparadas com a versão aprovada.'}</p><p class="small gap">${s.stage==='cause'?'Performance: atraso comprovado; causa inconclusiva.':'Performance: condições verificadas nos eventos disponíveis.'}</p><a class="btn text gap" href="${auditUrl(s,'documentos')}">Ver fontes →</a></section>`;}
function charges(s){return s.id==='0011'?[['Frete marítimo',3800,3800],['THC destino',550,550],['Documentation Fee',75,120],['Taxa adicional',0,150]]:[['Frete e taxas aprovadas',s.amount,s.billed]];}
function freight(s){if(s.billed===null)return `<div class="notice">${icon('info')}<p><strong>A cotação e o embarque já estão vinculados. Falta a cobrança.</strong>Quando a fatura chegar, a comparação continua automaticamente. Não há auditoria para iniciar nem formulário para repetir.</p></div><section class="panel gap"><div class="panel-body"><h2>Uma fonte faltante</h2><p class="gap">Fatura de frete de ${s.agent}, referente ao BL ${s.bl}. A Commercial Invoice da mercadoria não substitui essa cobrança.</p>${btn('Adicionar a fatura que falta','missing',`data-id="${s.id}"`,'primary gap','file')}<p class="small gap">Complemento necessário apenas porque este documento ainda não está disponível nas fontes conectadas.</p></div></section>`;
 return `<div class="notice ${s.stage==='ready'?'amber':'green'}">${icon('shield')}<p><strong>${s.stage==='ready'?'Diferença identificada. O caso já foi montado.':'Conferência concluída automaticamente.'}</strong>${s.stage==='ready'?'Argumentação e fontes foram reunidas sem uma etapa de validação da Freitas.':'Nenhuma aprovação ou encerramento manual é necessário nas verificações conformes.'}</p></div><section class="panel gap"><div class="panel-head"><div><h2>Aprovado × cobrado</h2><p>${qref(s)} · versão ${s.version} preservada</p></div>${btn('Ver referência','doc',`data-id="${s.id}" data-doc="quote"`,'text','file')}</div><div class="table-wrap"><table><thead><tr><th>Cobrança</th><th class="num">Aprovado</th><th class="num">Cobrado</th><th class="num">Diferença</th><th>Leitura</th></tr></thead><tbody>${charges(s).map(([name,a,b])=>`<tr class="${b>a?'highlight':''}"><td><strong>${name}</strong></td><td class="num">${a===0?'Não prevista':money(a)}</td><td class="num">${money(b)}</td><td class="num">${money(b-a)}</td><td>${tag(b>a?'Sustenta questionamento':'Conforme',b>a?'amber':'green')}</td></tr>`).join('')}<tr class="table-total"><td>Total</td><td class="num">${money(s.amount)}</td><td class="num">${money(s.billed)}</td><td class="num">${money(s.billed-s.amount)}</td><td></td></tr></tbody></table></div><div class="table-foot">Moeda e base de cobrança compatíveis · tolerância demonstrativa de 5% por linha · sem alteração posterior aprovada neste exemplo. Conclusões limitadas às fontes disponíveis.</div></section>${s.stage==='ready'?`<section class="panel gap"><div class="panel-body"><h2>Seu próximo passo já está preparado</h2><p class="gap">Um caso por cobrança, com todos os itens relacionados. Não é necessário abrir uma contestação para cada taxa ou reunir os anexos novamente.</p><a class="btn primary gap" href="${auditUrl(s,'resultado')}">Abrir caso pronto ${icon('arrow')}</a></div></section>`:''}`;}
function performance(s){const late=s.kind==='performance';return `<div class="notice ${late?'':'green'}">${icon(late?'info':'circle')}<p><strong>${late?'O atraso está demonstrado; a causa ainda não.':'Performance conferida com os eventos já disponíveis.'}</strong>${late?'O sistema não atribui responsabilidade nem reduz o score sem evidência. O pedido de esclarecimento já foi preparado.':'Cotação, booking, BL e tracking sustentam a leitura. Nenhuma ação necessária.'}</p></div><section class="panel gap"><div class="panel-head"><h2>Compromisso × realizado</h2></div><div class="table-wrap"><table><thead><tr><th>Condição</th><th>Aprovado</th><th>Realizado</th><th>Conclusão</th></tr></thead><tbody><tr><td>Transit time</td><td>35 dias</td><td>${late?43:35} dias</td><td>${tag(late?'+8 dias · causa pendente':'Conforme',late?'blue':'green')}</td></tr><tr><td>Free time</td><td>21 dias</td><td>21 dias</td><td>${tag('Conforme','green')}</td></tr><tr><td>Transbordos</td><td>1</td><td>1</td><td>${tag('Conforme','green')}</td></tr><tr><td>Comunicação de exceção</td><td>Até 24 h</td><td>${late?'20 h':'Sem exceção'}</td><td>${tag(late?'Conforme':'Não aplicável',late?'green':'')}</td></tr></tbody></table></div></section>${late?`<section class="panel gap"><div class="panel-body"><h3>Evite investigar do zero</h3><p class="gap">O pedido reúne prazo contratado, datas realizadas e o esclarecimento necessário: qual evento causou os oito dias adicionais e qual documento o comprova.</p><a class="btn primary gap" href="${auditUrl(s,'resultado')}">Abrir pedido de esclarecimento →</a><p class="small gap">Sem valor financeiro estimado. O destinatário deve confirmar a causa; o Centrix não a presume.</p></div></section>`:''}`;}
function documents(s){return `<div class="notice">${icon('link')}<p><strong>As evidências acompanham a jornada.</strong>O reaproveitamento depende das fontes conectadas e dos documentos disponíveis. Só lacunas que impedem uma conclusão pedem sua intervenção.</p></div><section class="panel gap"><div class="panel-head"><h2>Documentos e suas origens</h2></div><div class="documents-group"><div class="group-label">${icon('file')}Da cotação aprovada</div>${docRow(s,'Proposta comercial · v'+s.version,qref(s)+' · aprovação e versão preservadas','quote','Referência aprovada')}${docRow(s,s.reference,'Anexo da proposta aprovada','table')}${docRow(s,'Registro de aprovação','Condição autorizada pelo cliente','approval')}${s.version>1?docRow(s,'Versão '+(s.version-1)+' · anterior','Histórico preservado; não usada como referência','old','Histórica',''):''}<div class="group-label">${icon('ship')}Do gerenciamento de embarque</div>${docRow(s,'Booking confirmado','Conferido contra o compromisso original','booking')}${docRow(s,'BL final · '+s.bl,'Identificadores do mesmo processo','bl')}${docRow(s,'Commercial Invoice e Packing List','Documentos da mercadoria; não são a fatura de frete','cargo')}${docRow(s,'Eventos realizados','Tracking · partida e chegada','tracking')}<div class="group-label">${icon('shield')}Da cobrança</div>${s.billed===null?`<div class="doc-row"><div><strong>Fatura de frete · ausente</strong><p class="small">A comparação financeira aguarda esta fonte.</p></div>${btn('Adicionar','missing',`data-id="${s.id}"`,'small primary')}</div>`:docRow(s,'Fatura FAT-'+s.id,'Cobrança vinculada ao BL '+s.bl,'invoice')}<div class="group-label">${icon('file')}Preparado automaticamente</div><div class="doc-row"><div><strong>${s.stage==='ready'?'Caso para questionamento':s.stage==='cause'?'Pedido de esclarecimento':'Registro da conferência'}</strong><p class="small">${s.stage==='ready'?'Comparação, fundamento, mensagem e fontes.':s.stage==='cause'?'Atraso comprovado e evidência faltante.':'Sem necessidade de montagem manual.'}</p></div><a class="btn small" href="${auditUrl(s,s.stage==='ready'||s.stage==='cause'?'resultado':'frete')}">Ver</a></div></div></section><div class="notice gap">${icon('info')}<p>Booking ou fatura não sobrescrevem a proposta aprovada. Alteração comercial só passa a ser referência quando tiver aprovação rastreável.</p></div>`;}
function historyEvents(s){
 const late=s.kind==='performance',difference=caseValue(s)>0,items=[],reviewDate=s.documentAdded?'Nesta sessão':stamp(s,'invoice');
 const add=(date,phase,title,summary,tone,status,facts,sources=[],extra='')=>items.push({date,phase,title,summary,tone,status,facts,sources,extra});
 add(stamp(s,'approval'),'Cotação','Compromisso comercial preservado',`${qref(s)} · v${s.version} · ${money(s.amount)} aprovados.`,'green','Base definida',[
  ['O que entrou',`Proposta v${s.version}, anexo comercial e registro da aprovação do cliente.`],
  ['Referência da auditoria','35 dias de transit time, 21 dias de free time e 1 transbordo. Valores e condições ficam associados à versão aprovada.'],
  ['Continuidade','O embarque herda essa referência. Booking e cobrança posteriores não alteram o compromisso; uma mudança exige aprovação rastreável.']
 ],[['quote','Proposta aprovada'],['approval','Aprovação'],['table','Anexo comercial']]);
 add(stamp(s,'booking'),'Embarque','Booking vinculado à cotação','A reserva passou a compor o mesmo processo, sem repetir documentos.','green','Vínculo conferido',[
  ['O que entrou',`Booking de ${s.agent}, relacionado a ${qref(s)} e ${ref(s)}.`],
  ['O que foi conferido',`Correspondência da rota ${s.route} e vínculo com a referência aprovada. Nenhuma alteração comercial aprovada posterior foi localizada neste exemplo.`],
  ['Resultado','Referência comercial mantida. A reserva fica disponível como evidência operacional para as próximas conferências.']
 ],[['booking','Booking'],['quote','Referência comercial']]);
 add(stamp(s,'bl'),'Embarque','BL e partida incorporados à trilha',`BL ${s.bl} · contêiner ${s.container}.`,'green','Fontes reaproveitadas',[
  ['O que entrou','BL final e evento de partida, herdados do gerenciamento de embarque.'],
  ['O que foi conferido',`BL, contêiner e rota identificam ${ref(s)}. O evento de partida compõe a base para comparar o prazo realizado com os 35 dias aprovados.`],
  ['Resultado','A auditoria acompanha o processo com os documentos já vinculados. Commercial Invoice e Packing List permanecem como documentos da mercadoria; não substituem a fatura de frete.']
 ],[['bl','BL final'],['tracking','Eventos realizados']]);
 add(s.eta,'Performance',late?'Prazo realizado excedeu o compromisso':'Prazo e condições operacionais conferidos',late?'35 dias aprovados → 43 dias realizados. Primeiro desvio de prazo identificado.':'35 dias realizados, 21 dias de free time e 1 transbordo: condições atendidas.',late?'amber':'green',late?'+8 dias':'Sem desvio',[
  ['O que disparou a leitura','Eventos realizados disponíveis no encerramento do trajeto. O prazo foi calculado a partir da partida e da chegada registradas.'],
  ['Comparação',late?'Transit time: 35 dias aprovados × 43 dias realizados. Free time: 21 × 21 dias. Transbordos: 1 × 1. Comunicação de exceção: 20 h, dentro do compromisso de até 24 h.':'Transit time: 35 × 35 dias. Free time: 21 × 21 dias. Transbordos: 1 × 1. Comunicação de exceção: não aplicável.'],
  ['O que isso significa',late?'O atraso de 8 dias está demonstrado. Os documentos disponíveis não explicam a causa e não sustentam atribuição de responsabilidade ou impacto financeiro.':'Nenhum desvio nas condições verificadas. Conferência registrada automaticamente, sem aprovação ou encerramento manual.'],
  ['Desdobramento automático',late?'Prazo aprovado, datas realizadas e lacuna de causa foram separados para compor um pedido de esclarecimento. Nenhuma penalização de score por causa inconclusiva.':'Evidências preservadas. A conferência financeira continua de forma independente.']
 ],[['quote','Prazo aprovado'],['tracking','Prazo realizado'],['bl','BL final']]);
 if(s.kind==='missing')add('09 set','Cobrança','Fatura de frete ainda não encontrada',s.documentAdded?'Lacuna registrada antes do complemento desta sessão.':'A conferência financeira aguarda uma fonte; os demais vínculos estão completos.',s.documentAdded?'':'blue',s.documentAdded?'Lacuna superada':'Aguardando fonte',[
  ['O que foi encontrado','Cotação aprovada, aprovação, booking, BL e documentos da mercadoria já vinculados.'],
  ['O que faltava',`Cobrança do serviço de frete de ${s.agent}, referente ao BL ${s.bl}.`],
  ['Efeito na conclusão','Ausência de fatura não é divergência financeira. A comparação de valores permanece pendente até a fonte chegar.'],
  ['Continuidade',s.documentAdded?'A entrada posterior aparece abaixo; o registro da lacuna é preservado.':'A chegada pela fonte conectada retoma a conferência automaticamente. Adicionar a fatura é a única intervenção necessária se ela não chegar por essa fonte.']
 ],[['cargo','Documentos da mercadoria']],s.documentAdded?'':`<a class="btn small" href="${auditUrl(s,'documentos')}">Ver fonte faltante →</a>`);
 if(s.billed!==null){
  add(s.documentAdded?'Nesta sessão':stamp(s,'invoice'),'Cobrança',s.documentAdded?'Fatura adicionada e vínculo resolvido':'Fatura recebida e vinculada',`FAT-${s.id} · ${money(s.billed)} · mesmo BL do embarque.`,'green','Fonte disponível',[
   ['O que entrou',s.documentAdded?'Fatura demonstrativa adicionada pelo usuário nesta sessão.':'Fatura de frete disponibilizada para a conferência.'],
   ['O que foi conferido',`Emissor ${s.agent}, BL ${s.bl} e identificação do processo. A cobrança foi associada à cotação v${s.version}, sem novo cadastro do embarque.`],
   ['Desdobramento automático','Leitura das cobranças em USD e comparação com a referência aprovada. O recebimento da fatura não substitui a aprovação comercial.']
  ],[['invoice','Fatura de frete'],['bl','Vínculo pelo BL']]);
  const chargeTable=difference?`<div class="table-wrap trail-comparison"><table><caption>Itens que sustentam o questionamento</caption><thead><tr><th>Item</th><th class="num">Aprovado</th><th class="num">Cobrado</th><th class="num">Desvio</th></tr></thead><tbody>${charges(s).filter(([,a,b])=>b>a).map(([name,a,b])=>`<tr><td>${name}</td><td class="num">${a===0?'Não previsto':money(a)}</td><td class="num">${money(b)}</td><td class="num"><strong>+${money(b-a)}</strong></td></tr>`).join('')}</tbody></table></div>`:'';
  add(reviewDate,'Conferência financeira',difference?'Diferenças detectadas na comparação':'Cobrança de acordo com a referência',difference?`${money(s.amount)} aprovados → ${money(s.billed)} cobrados. ${money(caseValue(s))} para questionar.`:`${money(s.amount)} aprovados e cobrados. Nenhum desvio financeiro.`,difference?'amber':'green',difference?'Desvio identificado':'Sem desvio',[
   ['O que foi comparado',`FAT-${s.id} × ${qref(s)} v${s.version}. Moeda e base de cobrança compatíveis; tolerância demonstrativa de 5% por linha.`],
   ['Leitura dos itens',s.id==='0011'?'Frete marítimo e THC coincidem com o aprovado. Documentation Fee excede o aprovado em 60%; a taxa adicional não consta na referência.':difference?'O total faturado excede o valor aprovado. A composição detalhada não está representada neste exemplo; o questionamento usa a diferença total.':'Os valores disponíveis coincidem. Não há taxa ou diferença a levar ao fornecedor nas verificações cobertas.'],
   ['Efeito na conclusão',difference?'As diferenças sustentam um questionamento da cobrança. Ainda não há retificação, aceite do fornecedor ou economia realizada.':'Conferência financeira concluída sem intervenção. Um eventual desvio operacional continua separado.']
  ],[['quote','Valores aprovados'],['invoice','Valores cobrados']],chargeTable);
 }
 if(difference)add(reviewDate,'Fundamentação','Referências conferidas antes de montar o caso','As diferenças foram confrontadas com a aprovação e seus anexos.','blue','Base reunida',[
  ['O que foi verificado',`Versão ${s.version} aprovada, registro da aprovação e tabela comercial vinculada. Booking e fatura não foram usados como autorização de mudança de preço.`],
  ['Conclusão com as fontes disponíveis','Nenhuma aprovação posterior que justifique as diferenças foi localizada. A análise sustenta pedir retificação ou a condição aprovada que autorize a cobrança.'],
  ['Desdobramento automático',`${s.id==='0011'?'Os dois itens foram agrupados':'A diferença foi reunida'} em um único caso de ${money(caseValue(s))}, com referência, cobrança e identificação do embarque.`]
 ],[['approval','Registro de aprovação'],['table','Anexo comercial']]);
 if(difference||late)add(reviewDate,'Preparação',late?'Pedido de esclarecimento estruturado':'Caso e mensagem preparados',late?'O destinatário recebe o desvio demonstrado e a pergunta sobre a causa.':'Comparação, argumento e evidências reunidos para uso pelo cliente.','blue','Pronto para usar',[
  ['O que foi preparado',late?'Resumo dos 35 dias aprovados e 43 realizados, fontes das datas e mensagem solicitando o evento causador e o documento que o comprova.':`Pedido de revisão da FAT-${s.id}, diferenças identificadas, versão aprovada e evidências selecionadas.`],
  ['Destino sugerido',`${s.agent} · ${late?'responsável pela informação operacional':'emissor da cobrança'}. O cliente confirma o destinatário no seu canal habitual.`],
  ['Até onde o Centrix chegou','Caso pronto para baixar. Envio e tratativa acontecem fora do módulo; não há uma tarefa de validação ou negociação atribuída à Freitas.']
 ],[],`<a class="btn small" href="${auditUrl(s,'resultado')}">${late?'Ver pedido de esclarecimento':'Ver caso pronto'} →</a>`);
 if(s.exported)add('Nesta sessão','Uso do material','Material disponibilizado ao usuário','Foi realizado download ou cópia do material preparado.','','Exportado',[
  ['O que ficou registrado','Uso de uma das opções de exportação ou cópia nesta demonstração.'],
  ['O que ainda não é conhecido','O módulo não confirma envio, leitura pelo destinatário, resposta, retificação da cobrança ou recuperação de valor.']
 ]);
 return items;
}
function historyPage(s){
 const items=historyEvents(s),late=s.kind==='performance',difference=caseValue(s)>0;
 return `<section class="panel audit-trail"><div class="panel-head"><div><h2>O caminho até a conclusão</h2><p>Da condição aprovada ao caso preparado, com a evidência de cada leitura.</p></div>${tag(items.length+' registros na trilha')}</div><div class="trail-overview"><div><span class="eyebrow">Financeiro</span><strong>${s.billed===null?'Aguarda fatura':difference?money(caseValue(s))+' para questionar':'Conferido · sem desvio'}</strong></div><div><span class="eyebrow">Performance</span><strong>${late?'+8 dias · causa não comprovada':'Conferida · sem desvio'}</strong></div><p>Desvios e lacunas atuais estão abertos. Expanda as outras etapas para consultar o que foi verificado. Eventos demonstrativos.</p></div><ol class="audit-trail-list">${items.map(e=>`<li class="trail-event ${e.tone}"><details ${(e.tone==='amber'||e.status==='Aguardando fonte')?'open':''}><summary><span class="trail-date">${e.date}<span>${e.phase}</span></span><span class="trail-summary"><span class="trail-title">${e.title}</span><span class="trail-description">${e.summary}</span></span><span class="trail-status">${tag(e.status,e.tone)}<span class="trail-chevron" aria-hidden="true">⌄</span></span></summary><div class="trail-detail"><dl>${e.facts.map(([label,value])=>`<div><dt>${label}</dt><dd>${value}</dd></div>`).join('')}</dl>${e.extra}${e.sources.length?`<div class="trail-sources"><span>Fontes desta etapa</span>${e.sources.map(([key,label])=>btn(label,'doc',`data-id="${s.id}" data-doc="${key}"`,'small','file')).join('')}</div>`:''}</div></details></li>`).join('')}</ol><div class="trail-footer">${icon('shield')}Conferências limitadas às fontes disponíveis. Cada conclusão mantém sua referência; uma lacuna não vira desvio e um desvio não presume responsabilidade.</div></section>`;
}
function caseText(s){return s.kind==='performance'?`Solicitamos esclarecimento sobre o prazo realizado no embarque ${ref(s)}, BL ${s.bl}.\n\nA referência aprovada ${qref(s)}, versão ${s.version}, registra transit time de 35 dias. Os eventos realizados demonstram 43 dias, diferença de 8 dias.\n\nPor favor, informe o evento que originou o desvio e encaminhe a evidência correspondente. A documentação disponível ainda não permite atribuir responsabilidade.\n\nFontes: proposta aprovada, registro de aprovação, booking, BL e eventos de tracking.\n\nAgradecemos o retorno.`:`Solicitamos a revisão da fatura FAT-${s.id}, referente ao embarque ${ref(s)}, BL ${s.bl}.\n\nA referência formalmente aprovada é ${qref(s)}, versão ${s.version}, com valor de ${money(s.amount)}. A cobrança recebida totaliza ${money(s.billed)}, diferença de ${money(caseValue(s))}.\n\n${s.id==='0011'?'Documentation Fee: USD 75 aprovados e USD 120 cobrados, diferença de USD 45. Taxa adicional: USD 150 sem previsão localizada na condição aprovada.':'O total faturado supera o compromisso aprovado em USD 320, sem alteração posterior aprovada nas fontes disponíveis.'}\n\nSolicitamos a retificação da cobrança ou o envio da condição aprovada que justifique a diferença.\n\nAs referências e evidências estão reunidas no dossiê anexo.\n\nAgradecemos o retorno.`;}
function resultPage(s){if(!['ready','cause'].includes(s.stage))return `<div class="notice ${s.billed===null?'':'green'}">${icon('shield')}<p><strong>${s.billed===null?'Ainda não há base para um caso financeiro.':'Nenhum questionamento necessário.'}</strong>${s.billed===null?'Falta a fatura de frete. A análise continua quando ela estiver disponível.':'As condições conferidas estão de acordo com as fontes. Você não precisa aprovar, encerrar ou registrar um resultado.'}</p></div><a class="btn gap" href="${auditUrl(s,s.billed===null?'documentos':'frete')}">Ver ${s.billed===null?'fonte faltante':'conferência'} →</a>`;const late=s.kind==='performance';return `<section class="result-hero case-hero">${icon('file')}<div><h2>${late?'Pedido de esclarecimento pronto':'Caso pronto para questionar a cobrança'}</h2><p>${late?'O desvio está demonstrado. A causa precisa de evidência.':'Diferença, fundamento, referência aprovada e mensagem reunidos.'}</p>${late?'':`<div class="result-big" style="color:var(--indigo)">${money(caseValue(s))}</div>`}</div></section><section class="panel"><div class="panel-head"><div><h2>Revise se precisar. O material já está pronto.</h2><p>${ref(s)} · ${qref(s)} v${s.version} · FAT-${s.id}</p></div>${btn('Baixar e-mail + evidências','export-email',`data-id="${s.id}"`,'primary','down')}</div><div class="panel-body"><dl class="facts"><div><dt>Destinatário sugerido</dt><dd>${s.agent} · ${late?'responsável pela informação operacional':'emissor da cobrança'}</dd></div><div><dt>Objetivo</dt><dd>${late?'Obter a causa documentada, sem atribuição antecipada de culpa.':'Solicitar retificação ou evidência da condição que autoriza a diferença.'}</dd></div></dl><details class="gap"><summary style="cursor:pointer;color:var(--indigo);font-weight:600">Conferir fundamento e referências</summary><p class="gap">${late?'35 dias aprovados × 43 dias realizados. Causa não demonstrada.':'Comparação em USD com a referência aprovada. Tolerância demonstrativa de 5% excedida; nenhuma alteração posterior autorizada localizada.'}</p>${docRow(s,'Proposta aprovada · v'+s.version,'Referência comercial preservada','quote')}${docRow(s,late?'Eventos do embarque':'Fatura FAT-'+s.id,late?'Fonte das datas realizadas':'Fonte da cobrança',late?'tracking':'invoice')}</details><label class="field">Mensagem pronta para uso<textarea id="prepared-message" style="min-height:230px">${escapeHTML(s.message||caseText(s))}</textarea></label><p class="small">O e-mail é baixado como rascunho, com o dossiê e as evidências demonstrativas anexos. Confirme o destinatário e envie pelo seu canal habitual.</p><div class="heading-actions gap" style="justify-content:flex-start;flex-wrap:wrap">${btn('Copiar mensagem','copy-message',`data-id="${s.id}"`,'','file')}${btn('Baixar dossiê','export-case',`data-id="${s.id}"`,'','down')}</div><div id="export-status" class="source-label gap">${s.exported?icon('check')+'Material exportado. Envio não confirmado.':''}</div></div></section><div class="notice gap">${icon('info')}<p><strong>A atuação do módulo termina na preparação do caso.</strong>Envio, negociação e eventual recuperação acontecem fora do Centrix. Baixar o material não significa que o fornecedor foi contatado nem que o valor foi recuperado.</p></div>`;}
function missingDrawer(s){openDrawer('Só falta a fatura de frete',`<p>${ref(s)} · ${s.bl}. Cotação, aprovação, booking e BL já estão vinculados.</p><div class="notice">${icon('link')}<p><strong>Sem cadastro repetido nem aprovação por documento.</strong>O vínculo usa os identificadores da jornada. Se houver conflito de processo ou leitura inconclusiva, só o campo afetado pede revisão.</p></div><div class="document-sheet"><strong>Fatura-demonstrativa-${s.id}.txt</strong><p class="gap">${s.agent} · ${money(s.amount)}<br>BL ${s.bl} · ${ref(s)}</p></div><p class="small">No produto integrado, a entrada virá da fonte disponível ou do arquivo adicionado pelo cliente. Esta demonstração usa uma fonte de exemplo e simula identificação, vínculo e comparação.</p>`,`${btn('Voltar','close')}${btn('Usar fatura de exemplo','submit-doc',`data-id="${s.id}"`,'primary')}`,'COMPLEMENTO · UMA ÚNICA FONTE');}
function evidenceText(s,key){const common=`DEMONSTRAÇÃO DE UX — NÃO É DOCUMENTO COMERCIAL REAL\n${ref(s)} | ${qref(s)} v${s.version} | BL ${s.bl}\n`;const facts={quote:`Referência aprovada: ${money(s.amount)}. Transit time: 35 dias. Free time: 21 dias. Transbordos: 1.${s.id==='0011'?' Frete: USD 3800. THC: USD 550. Documentation Fee: USD 75. Taxa adicional: não prevista.':''}`,table:`Anexo de referência: ${s.reference}. Mesmas condições da proposta aprovada.`,approval:`Aprovação do cliente: versão ${s.version}, em ${stamp(s,'approval')} de 2026. Nenhuma alteração posterior aprovada neste exemplo.`,old:`Versão ${s.version-1} preservada no histórico. Não usada como referência.`,invoice:`FAT-${s.id}: ${money(s.billed)}. Emissor: ${s.agent}.${s.id==='0011'?' Frete: USD 3800. THC: USD 550. Documentation Fee: USD 120. Taxa adicional: USD 150.':''}`,booking:`Booking de ${s.agent}, vinculado à cotação aprovada. Conhecimento ${s.bl}.`,bl:`BL ${s.bl}. Contêiner ${s.container}. Rota ${s.route}.`,cargo:'Commercial Invoice e Packing List identificam mercadoria, volumes e peso. Não substituem a fatura do serviço de frete.',tracking:`Transit time realizado: ${s.kind==='performance'?43:35} dias. Liberação: ${s.eta}. Free time: 21 dias. Transbordos: 1.`};return common+(facts[key]||facts.quote);}
function docDrawer(s,key){const title=({quote:'Proposta aprovada',table:s.reference,approval:'Registro de aprovação',old:'Versão anterior',booking:'Booking confirmado',bl:'BL final',cargo:'Documentos da mercadoria',invoice:'Fatura de frete',tracking:'Eventos realizados'})[key]||'Evidência';openDrawer(title,`<div class="source-label">${icon('link')}${qref(s)} → ${ref(s)}</div><div class="document-sheet"><div class="doc-title">${title}</div><p style="white-space:pre-wrap;color:var(--text)">${escapeHTML(evidenceText(s,key))}</p></div><p class="small">Representação ilustrativa. A implementação deve abrir e anexar o arquivo original vinculado, preservando versão e origem.</p>`,`${btn('Fechar','close')}${btn('Ver todos os vínculos','goto-docs',`data-id="${s.id}"`,'','link')}`,'EVIDÊNCIA · ORIGEM PRESERVADA');}
function downloadFile(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function saveMessage(s){s.message=$('#prepared-message')?.value||s.message||caseText(s);return s.message;}
function dossier(s){const list=s.kind==='performance'?['quote','approval','booking','bl','tracking']:['quote','approval','invoice','bl'];return `<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Dossiê ${ref(s)}</title><style>body{font:16px/1.5 Arial;color:#272b43;max-width:850px;margin:50px auto;padding:20px}h1,h2{color:#2c2e65}pre{white-space:pre-wrap;background:#f4f5fa;padding:18px;border:1px solid #dde0ee}small{color:#626880}@media print{body{margin:0}}</style><h1>${s.kind==='performance'?'Pedido de esclarecimento':'Caso para questionamento'} · ${ref(s)}</h1><p><strong>Referência:</strong> ${qref(s)} v${s.version} · ${s.bl}</p><p><strong>Destino sugerido:</strong> ${s.agent}</p><p><strong>Escopo:</strong> ${s.kind==='performance'?'Esclarecimento de causa. Sem atribuição de responsabilidade.':money(caseValue(s))+' para questionar. Não é economia realizada.'}</p><h2>Mensagem</h2><pre>${escapeHTML(s.message||caseText(s))}</pre><h2>Evidências selecionadas</h2>${list.map(k=>`<pre>${escapeHTML(evidenceText(s,k))}</pre>`).join('')}<h2>Limitações</h2><p>Material demonstrativo. Não contém os documentos comerciais originais. No produto integrado, as fontes originais vinculadas compõem o pacote. O Centrix prepara a análise e a comunicação; envio, negociação e recuperação ficam fora deste escopo.</p></html>`;}
function base64utf8(text){const bytes=new TextEncoder().encode(text);let binary='';for(const b of bytes)binary+=String.fromCharCode(b);return btoa(binary);}
function emailDraft(s){const boundary='centrix-demo-'+s.id,parts=[];const add=(type,name,text)=>parts.push(`--${boundary}\r\nContent-Type: ${type}; charset=UTF-8${name?'; name="'+name+'"':''}\r\nContent-Transfer-Encoding: base64\r\n${name?'Content-Disposition: attachment; filename="'+name+'"\r\n':''}\r\n${base64utf8(text).match(/.{1,76}/g).join('\r\n')}\r\n`);add('text/plain','',s.message||caseText(s));add('text/html','Dossie-'+s.id+'-DEMO.html',dossier(s));for(const k of (s.kind==='performance'?['quote','approval','booking','bl','tracking']:['quote','approval','invoice','bl']))add('text/plain',k+'-'+s.id+'-DEMO.txt',evidenceText(s,k));return `X-Unsent: 1\r\nMIME-Version: 1.0\r\nSubject: ${s.kind==='performance'?'Esclarecimento de prazo':'Revisao de cobranca'} | ${ref(s)}\r\nContent-Type: multipart/mixed; boundary="${boundary}"\r\n\r\n${parts.join('')}--${boundary}--\r\n`;}
function markExported(s){s.exported=true;if($('#export-status'))$('#export-status').textContent='Material exportado. Envio ao destinatário não confirmado.';}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const s=get(b.dataset.id);switch(b.dataset.action){
case 'menu':document.body.classList.toggle('menu-open');break;
case 'close':$('#drawer').close();break;
case 'filter':filter=b.dataset.filter;$('#overview-body').innerHTML=portfolio();break;
case 'clear':filter='all';search='';$('#overview-body').innerHTML=portfolio();break;
case 'missing':missingDrawer(s);break;
case 'submit-doc':s.billed=s.amount;s.stage='clean';s.documentAdded=true;render();toast('Fonte vinculada e conferência simulada concluída. Nenhuma divergência.');break;
case 'doc':docDrawer(s,b.dataset.doc);break;
case 'goto-docs':$('#drawer').close();location.hash=auditUrl(s,'documentos');break;
case 'export-email':saveMessage(s);downloadFile('Caso-'+s.id+'-DEMO.eml',emailDraft(s),'message/rfc822');markExported(s);toast('Rascunho com anexos baixado. Confira o destinatário no seu e-mail; nenhum envio foi realizado.');break;
case 'export-case':saveMessage(s);downloadFile('Dossie-'+s.id+'-DEMO.html',dossier(s),'text/html;charset=utf-8');markExported(s);toast('Dossiê demonstrativo baixado.');break;
case 'copy-message':saveMessage(s);try{await navigator.clipboard.writeText(s.message);markExported(s);toast('Mensagem copiada. Nenhum envio foi realizado.');}catch{$('#prepared-message').focus();$('#prepared-message').select();toast('Texto selecionado. Use Ctrl+C para copiar.');}break;
case 'reset':openDrawer('Reiniciar demonstração','<p>Os vínculos simulados e registros locais de exportação voltam ao estado inicial. Os arquivos baixados permanecem com você.</p>',btn('Voltar','close')+btn('Reiniciar','confirm-reset','','primary'),'PROTÓTIPO');break;
case 'confirm-reset':records=structuredClone(seed);filter='all';search='';$('#drawer').close();if(location.hash==='#auditoria')render();else location.hash='#auditoria';break;
}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;$('#audit-list').innerHTML=rows();}if(e.target.id==='prepared-message')get(route.id).message=e.target.value;});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
render();
